//! Compares the gradients of every operation with an implemented backward formula with PyTorch's,
//! using `tests/golden/grads.safetensors` generated by `tools/golden/gen_grads.py`. Each case in
//! that file must have a handler here, and every tensor of a case must be used. Floating point
//! inputs are the variables; a gradient PyTorch returns as `None` is not stored, and must be
//! `None` here too. Run in debug and release profiles.

mod common;

use std::collections::BTreeMap;

use common::{Case, Golden, assert_close_tol, tolerance};
use homura::autograd::{self, GradOptions};
use homura::{DType, GeluApproximate, NewAxis, Tensor, where_};

/// The output of operation `op` of a case, from its inputs by name.
fn forward(op: &str, t: &BTreeMap<String, Tensor>) -> Option<Tensor> {
    let (x, y, z) = (|| &t["x"], || &t["y"], || &t["z"]);
    let idx = || &t["idx"];
    Some(match op {
        "neg" => x().neg(),
        "exp" => x().exp(),
        "erf" => x().erf(),
        "sign" => x().sign(),
        "add" | "add_inf" => x() + y(),
        "sub" => x() - y(),
        "mul" | "mul_int" => x() * y(),
        "mul_self" => x() * x(),
        "add_scalar" => x() + 2.5,
        "rsub_scalar" => 1.5 - x(),
        "mul_scalar" if x().dtype() == DType::F32 => 1.7 * x(),
        "mul_scalar" => x() * std::f64::consts::FRAC_2_SQRT_PI,
        "sum" => x().sum(),
        "sum_to_size" => x().sum_to_size([1, 4]),
        "expand" => x().expand([2, 3, 4]),
        "view" => x().view([4, 3]),
        "reshape_copy" => x().index((.., (0..).step_by(2))).reshape([6]),
        "select" => x().select(-1, -2),
        "narrow" => x().narrow(0, 1, 2),
        "slice_step" => x().index((1.., (0..).step_by(3))),
        "index_int" => x().index(idx()),
        "index_select" if x().num_dims() == 1 => x().index_select(0, idx()),
        "index_select" => x().index_select(1, idx()),
        "as_strided" if x().num_elements() == 3 => x().as_strided([3], [0], 1),
        "as_strided" => x().as_strided([3, 2], [1, 1], 1),
        "index_add" => x().index_add(0, idx(), &t["source"]),
        "gather" => x().gather(1, idx()),
        "scatter_add" => x().scatter_add(0, idx(), &t["src"]),
        "select_scatter" => x().select_scatter(&t["src"], 1, -1),
        "slice_scatter" => x().slice_scatter(&t["src"], 1, Some(1), None, 2),
        "deep_clone" => x().deep_clone(),
        "to_f64" => x().to(DType::F64),
        "to_f16" => x().to(DType::F16),
        "abs" => x().abs(),
        "relu" => x().relu(),
        "log" => x().log(),
        "sqrt" => x().sqrt(),
        "rsqrt" => x().rsqrt(),
        "reciprocal" => x().reciprocal(),
        "sin" => x().sin(),
        "cos" => x().cos(),
        "tanh" => x().tanh(),
        "sigmoid" => x().sigmoid(),
        "silu" => x().silu(),
        "gelu" => x().gelu(GeluApproximate::None),
        "gelu_tanh" => x().gelu(GeluApproximate::Tanh),
        "div" | "div_int" | "int_div" => x() / y(),
        "div_scalar" => x() / 1.7,
        "rdiv_scalar" => 1.5 / x(),
        "rdiv_zero" => 0.0 / x(),
        "where" => where_(&t["cond"], x(), y()),
        "where_scalar" => where_(&t["cond"], 0.5, x()),
        "pow" | "pow_int" | "int_pow" => x().pow(y()),
        "pow_scalar" => x().pow(2.5),
        "pow_zero" => x().pow(0),
        "maximum" => x().maximum(y()),
        "minimum" => x().minimum(y()),
        "maximum_scalar" => x().maximum(0.5),
        "minimum_scalar" => x().minimum(0.5),
        "clamp" => x().clamp(&t["lo"], &t["hi"]),
        "clamp_scalar" => x().clamp(-0.5, 0.5),
        "clamp_min" => x().clamp_min(y()),
        "clamp_max" => x().clamp_max(y()),
        "clamp_min_scalar" => x().clamp_min(-0.5),
        "clamp_max_scalar" => x().clamp_max(0.5),
        "clamp_equal" => x().clamp(0.5, 0.5),
        "clamp_reversed" => x().clamp(0.5, -0.5),
        "clamp_nan_min" => x().clamp(f64::NAN, 0.5),
        "clamp_nan_max" => x().clamp(-0.5, f64::NAN),
        "clamp_mixed_min" => x().clamp(-0.5, &t["hi"]),
        "clamp_mixed_max" => x().clamp(&t["lo"], 0.5),
        "clamp_mixed_round" => x().clamp(1.0002, &t["hi"]),
        "masked_fill" => x().masked_fill(&t["cond"], &t["value"]),
        "masked_fill_scalar" => x().masked_fill(&t["cond"], 0.5),
        "addcmul" => x().addcmul(y(), &t["z"], 1.7),
        "addcdiv" => x().addcdiv(y(), &t["z"], -0.3),
        "addcmul_zero_large" => x().addcmul(y(), &t["z"], 0.0),
        "addcmul_scaled" => x().addcmul(y(), &t["z"], 1e-10),
        "addcmul_underflow" => x().addcmul(y(), &t["z"], 1e20),
        "addcmul_small" => x().addcmul(y(), &t["z"], 0.001),
        "addcdiv_small" => x().addcdiv(y(), &t["z"], 0.001),
        "addcdiv_tenth" => x().addcdiv(y(), &t["z"], 0.1),
        "addcdiv_three_tenths" => x().addcdiv(y(), &t["z"], 0.3),
        "addcdiv_factor" => x().addcdiv(y(), &t["z"], 1.7),
        "lerp" => x().lerp(y(), &t["z"]),
        "lerp_low" => x().lerp(y(), 0.2),
        "lerp_high" => x().lerp(y(), 0.8),
        "sum_dim" => x().sum_dim(1, false),
        "sum_dims_keep" => x().sum_dim([0, 2], true),
        "mean" => x().mean(),
        "mean_dim" => x().mean_dim(-1, false),
        "mean_dims_keep" => x().mean_dim([0, 1], true),
        "prod" | "prod_zero" | "prod_two_zeros" | "prod_overflow" | "prod_order_bf16" => x().prod(),
        "prod_dim"
        | "prod_dim_zeros"
        | "prod_dim_overflow"
        | "prod_dim_order_f64"
        | "prod_dim_order_f32"
        | "prod_dim_order_f16"
        | "prod_dim_order_bf16" => x().prod_dim(1, false),
        "prod_dim_keep" => x().prod_dim(0, true),
        "max" | "max_ties" => x().max(),
        "min" => x().min(),
        "max_dim" => x().max_dim(1, false).values,
        "min_dim_keep" => x().min_dim(0, true).values,
        "var" => x().var(1),
        "var_c2" => x().var(2),
        "var_c4" => x().var(4),
        "var_dim" => x().var_dim(1, 1, false),
        "var_dim_c3" => x().var_dim(1, 3, false),
        "var_dim_c4" => x().var_dim(1, 4, false),
        "var_dims_keep" => x().var_dim([0, 1], 0, true),
        "std" => x().std(1),
        "std_c3" => x().std(3),
        "std_dim" => x().std_dim(0, 2, false),
        "std_dim_c4" => x().std_dim(1, 4, false),
        "permute" => x().permute([2, 0, 1]),
        "transpose" => x().transpose(-1, 0),
        "squeeze" => x().squeeze(),
        "squeeze_dim" => x().squeeze_dim(-1),
        "squeeze_dims" => x().squeeze_dim([1, 3]),
        "squeeze_none" => x().squeeze_dim(Vec::<i64>::new()),
        "unsqueeze" => x().unsqueeze(if x().num_dims() == 1 { 0 } else { 1 }),
        "flatten" => x().flatten(1, 2),
        "index_alias" => x().index((.., ..)),
        "index_mixed" => x().index((.., 1.., NewAxis, (0..).step_by(2))),
        "index_full_tensor" => x().index((.., idx())),
        "concat" => homura::concat(&[x(), &t["e"], y()], -1),
        "concat_dtypes" => homura::concat(&[x(), y(), &t["n"]], 0),
        "stack" => homura::stack(&[x(), y()], 1),
        "flip" => x().flip([0, 2]),
        "triu" => x().triu(1),
        "tril" => x().tril(-1),
        "repeat" => x().repeat([2, 1, 2]),
        op if op.starts_with("matmul_") => x().matmul(y()),
        "addmm" => x().addmm(y(), z(), 2.0, -1.5),
        "addmm_beta0" => x().addmm(y(), z(), 0, 1.5),
        "addmm_alpha0" => x().addmm(y(), z(), 1, 0),
        "addmm_alpha_large" => x().addmm(y(), z(), 1, 1e30),
        "addmm_opmath_f16" => x().addmm(y(), z(), 1.0004, 1.0004),
        "addmv" => x().addmv(y(), z(), -0.5, 2),
        "addr" => x().addr(y(), z(), 1.5, 0.75),
        "baddbmm" => x().baddbmm(y(), z(), 0.5, -1),
        "addbmm" => x().addbmm(y(), z(), 0.25, 3),
        "softmax_dim1" => x().softmax(1),
        "softmax_last" | "softmax_masked" | "softmax_opmath_f16" => x().softmax(-1),
        "log_softmax_dim0" => x().log_softmax(0),
        "log_softmax_last" | "log_softmax_masked" | "log_softmax_opmath_bf16" => {
            x().log_softmax(-1)
        }
        "add_" | "add_promote_" => in_place(x(), |c| _ = c.add_(y())),
        "add_scalar_" => in_place(x(), |c| _ = c.add_(2.5)),
        "add_self_" => in_place(x(), |c| _ = c.add_(c)),
        "sub_" => in_place(x(), |c| _ = c.sub_(y())),
        "mul_" | "mul_promote_" => in_place(x(), |c| _ = c.mul_(y())),
        "mul_scalar_" => in_place(x(), |c| _ = c.mul_(-1.7)),
        "div_" => in_place(x(), |c| _ = c.div_(y())),
        "pow_" => in_place(x(), |c| _ = c.pow_(y())),
        "pow_scalar_" => in_place(x(), |c| _ = c.pow_(2.5)),
        "clamp_" => in_place(x(), |c| _ = c.clamp_(&t["lo"], &t["hi"])),
        "clamp_scalar_" => in_place(x(), |c| _ = c.clamp_(-0.5, 0.5)),
        "clamp_promoted_" => in_place(x(), |c| _ = c.clamp_(&t["lo"], 1.0 + 2f64.powi(-30))),
        "masked_fill_" => in_place(x(), |c| _ = c.masked_fill_(&t["cond"], &t["value"])),
        "addcmul_" => in_place(x(), |c| _ = c.addcmul_(y(), z(), 1.7)),
        "addcdiv_" => in_place(x(), |c| _ = c.addcdiv_(y(), z(), -0.3)),
        "lerp_" => in_place(x(), |c| _ = c.lerp_(y(), z())),
        "lerp_scalar_" => in_place(x(), |c| _ = c.lerp_(y(), 0.3)),
        "index_add_" => in_place(x(), |c| _ = c.index_add_(0, idx(), &t["source"])),
        "scatter_add_" => in_place(x(), |c| _ = c.scatter_add_(0, idx(), &t["src"])),
        "chain_" => in_place(x(), |c| {
            c.add_(y()).mul_(y()).div_(y().exp()).pow_(2.0);
        }),
        "mul_promote_bcast_" => in_place(x(), |c| _ = c.mul_(y())),
        "add_promote_bcast_" => in_place(x(), |c| _ = c.add_(y())),
        "copy_" | "copy_promote_" | "copy_int_" => in_place(x(), |c| _ = c.copy_(y())),
        "fill_" => in_place(x(), |c| _ = c.fill_(2.5)),
        "zero_" => in_place(x(), |c| _ = c.zero_()),
        _ => return None,
    })
}

/// `f` applied in place to a copy of `x` with the history of `x` (PyTorch's `x.clone()`).
fn in_place(x: &Tensor, f: impl FnOnce(&Tensor)) -> Tensor {
    let c = x.deep_clone();
    f(&c);
    c
}

/// Cases whose f64 operand `y` is broadcast over an f32 self, so that its gradient is summed in
/// f32 before it is converted.
const SUMMED_IN_F32: [&str; 2] = ["mul_promote_bcast_", "add_promote_bcast_"];

/// Runs one case and checks its gradients. Returns `false` if there is no handler for it.
fn run(c: &Case) -> bool {
    let (category, op) = c.name.split_once('.').unwrap();
    let mut inputs = BTreeMap::new();
    for name in c.golden.names(c.name) {
        if name != "g" && !name.starts_with("grad_") {
            let t = c.input(&name);
            t.requires_grad_(t.is_floating_point());
            inputs.insert(name, t);
        }
    }
    let Some(out) = forward(op, &inputs) else {
        return false;
    };
    let variables: Vec<(&String, &Tensor)> =
        inputs.iter().filter(|(_, t)| t.requires_grad()).collect();
    let options = GradOptions {
        grad_outputs: vec![Some(c.input("g"))],
        allow_unused: true,
        ..Default::default()
    };
    let refs: Vec<&Tensor> = variables.iter().map(|(_, t)| *t).collect();
    let grads = autograd::grad(&[&out], &refs, options);
    let stored = c.golden.names(c.name);
    for ((name, _), grad) in variables.iter().zip(grads) {
        let key = format!("grad_{name}");
        let what = format!("{}/{key}", c.name);
        match grad {
            Some(grad) if stored.contains(&key) => {
                // f32 within atol = rtol = 1e-5, half precision within the dtype's precision,
                // and non-finite cases exactly. The f64 gradient of the wider operand y broadcast
                // over self in SUMMED_IN_F32 is summed in f32 (by the reference, while homura
                // sums in f64 and rounds once), so it agrees to f32 precision.
                let (rtol, atol) = match (category, grad.dtype()) {
                    ("special", _) => (0.0, 0.0),
                    (_, DType::F32) => (1e-5, 1e-5),
                    (_, DType::F64) if SUMMED_IN_F32.contains(&op) && name.as_str() == "y" => {
                        (1e-5, 1e-5)
                    }
                    (_, dtype) => tolerance(dtype),
                };
                c.check_with(&key, &grad, |a, e| {
                    assert_close_tol(a, e, rtol, atol, &what)
                });
            }
            Some(grad) => panic!("{what}: PyTorch has no gradient, got {grad:?}"),
            None => assert!(!stored.contains(&key), "{what}: no gradient"),
        }
    }
    true
}

#[test]
fn gradients_match_pytorch() {
    let golden = Golden::load("grads.safetensors");
    let cases = golden.cases();
    assert!(cases.len() >= 350, "only {} cases", cases.len());
    let mut missing = vec![];
    for name in &cases {
        let c = Case::new(&golden, name);
        if run(&c) {
            c.assert_all_used();
        } else {
            missing.push(name.clone());
        }
    }
    assert!(missing.is_empty(), "cases without a handler: {missing:?}");
}
